<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { MoreFilled } from '@element-plus/icons-vue'
import { createAdvertisement, createAdvertisementSlot, deleteAdvertisement, deleteAdvertisementSlot, listAdvertisements, listAdvertisementSlots, updateAdvertisement, updateAdvertisementSlot, type Advertisement, type AdvertisementDraft, type AdvertisementSlot, type AdvertisementSlotDraft } from '../../api/advertisements'
const slots=ref<AdvertisementSlot[]>([]),ads=ref<Advertisement[]>([]),activeId=ref<number|null>(null),loading=ref(false),slotDialog=ref(false),adDialog=ref(false),saving=ref(false),editingSlot=ref<number|null>(null),editingAd=ref<number|null>(null)
const slotForm=reactive<AdvertisementSlotDraft>({code:'',name:'',description:'',sortOrder:0,enabled:true,system:false})
const adForm=reactive<AdvertisementDraft>({title:'',imagePath:'',url:null,openMode:'DEFAULT',startAt:null,endAt:null,sortOrder:0,enabled:true})
const active=computed(()=>slots.value.find(i=>i.id===activeId.value)||null),asAd=(row:unknown)=>row as Advertisement
onMounted(refresh)
async function refresh(){loading.value=true;try{slots.value=await listAdvertisementSlots();if(!slots.value.some(i=>i.id===activeId.value))activeId.value=slots.value[0]?.id||null;await refreshAds()}catch(e){ElMessage.error(msg(e))}finally{loading.value=false}}
async function refreshAds(){ads.value=activeId.value?await listAdvertisements(activeId.value):[]}
async function select(id:number){activeId.value=id;await refreshAds()}
function addSlot(){editingSlot.value=null;Object.assign(slotForm,{code:'',name:'',description:'',sortOrder:0,enabled:true,system:false});slotDialog.value=true}
function editSlot(row:AdvertisementSlot){editingSlot.value=row.id;Object.assign(slotForm,{code:row.code,name:row.name,description:row.description,sortOrder:row.sortOrder,enabled:row.enabled,system:row.system});slotDialog.value=true}
async function saveSlot(){saving.value=true;try{const saved=editingSlot.value?await updateAdvertisementSlot(editingSlot.value,{...slotForm}):await createAdvertisementSlot({...slotForm});slotDialog.value=false;activeId.value=saved.id;await refresh()}catch(e){ElMessage.error(msg(e))}finally{saving.value=false}}
async function removeSlot(row:AdvertisementSlot){try{await ElMessageBox.confirm(`删除广告位“${row.name}”将同时删除广告内容，是否继续？`,'删除广告位',{type:'warning'});await deleteAdvertisementSlot(row.id);await refresh()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(msg(e))}}
function addAd(){editingAd.value=null;Object.assign(adForm,{title:'',imagePath:'',url:null,openMode:'DEFAULT',startAt:null,endAt:null,sortOrder:0,enabled:true});adDialog.value=true}
function editAd(row:Advertisement){editingAd.value=row.id;Object.assign(adForm,{title:row.title,imagePath:row.imagePath,url:row.url,openMode:row.openMode,startAt:row.startAt,endAt:row.endAt,sortOrder:row.sortOrder,enabled:row.enabled});adDialog.value=true}
async function saveAd(){if(!activeId.value)return;saving.value=true;try{editingAd.value?await updateAdvertisement(activeId.value,editingAd.value,{...adForm}):await createAdvertisement(activeId.value,{...adForm});adDialog.value=false;await refreshAds()}catch(e){ElMessage.error(msg(e))}finally{saving.value=false}}
async function removeAd(row:Advertisement){if(!activeId.value)return;try{await ElMessageBox.confirm(`确定删除广告“${row.title}”吗？`,'删除广告',{type:'warning'});await deleteAdvertisement(activeId.value,row.id);await refreshAds()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(msg(e))}}
const msg=(e:unknown)=>e instanceof Error?e.message:'操作失败'
</script>
<template><main class="admin-shell"><header class="page-header"><div><p class="eyebrow">推广内容</p><h1>广告管理</h1><p class="subtitle">广告位定义固定展示区域，广告内容负责图片、链接、排序和可选有效期。</p></div><el-button data-testid="add-ad-slot" type="primary" @click="addSlot">新增广告位</el-button></header><div style="display:grid;grid-template-columns:260px minmax(0,1fr);gap:16px;align-items:start"><el-card shadow="never"><div style="display:flex;flex-direction:column"><div v-for="slot in slots" :key="slot.id" :data-testid="`ad-slot-${slot.code}`" :style="{display:'flex',alignItems:'center',minHeight:'44px',padding:'0 6px 0 12px',borderRadius:'6px',cursor:'pointer',background:activeId===slot.id?'var(--el-fill-color-light)':'transparent'}" @click="select(slot.id)"><span style="flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">{{slot.name}}</span><span @click.stop><el-dropdown trigger="click" @command="command=>command==='edit'?editSlot(slot):removeSlot(slot)"><el-button text circle aria-label="广告位操作"><el-icon><MoreFilled/></el-icon></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="edit">编辑</el-dropdown-item><el-dropdown-item command="delete" divided>删除</el-dropdown-item></el-dropdown-menu></template></el-dropdown></span></div></div></el-card><el-card shadow="never"><template #header><div style="display:flex;justify-content:space-between;align-items:center"><div><strong>{{active?.name||'请选择广告位'}}</strong><span v-if="active" style="margin-left:8px;color:#909399">{{active.code}}</span></div><el-button data-testid="add-advertisement" type="primary" :disabled="!active" @click="addAd">新增广告</el-button></div></template><el-table v-loading="loading" :data="ads" row-key="id" data-testid="advertisement-table"><el-table-column prop="title" label="标题" min-width="180"/><el-table-column prop="imagePath" label="图片" min-width="220" show-overflow-tooltip/><el-table-column prop="url" label="链接" min-width="220" show-overflow-tooltip/><el-table-column prop="sortOrder" label="排序" width="80"/><el-table-column label="状态" width="80"><template #default="s">{{asAd(s.row).enabled?'启用':'停用'}}</template></el-table-column><el-table-column label="操作" width="130"><template #default="s"><el-button link type="primary" @click="editAd(asAd(s.row))">编辑</el-button><el-button link type="danger" @click="removeAd(asAd(s.row))">删除</el-button></template></el-table-column></el-table></el-card></div><el-dialog v-model="slotDialog" :title="editingSlot?'编辑广告位':'新增广告位'" width="560px"><el-form label-width="100px"><el-form-item label="Code"><el-input v-model="slotForm.code" :disabled="Boolean(editingSlot)"/></el-form-item><el-form-item label="名称"><el-input v-model="slotForm.name"/></el-form-item><el-form-item label="说明"><el-input v-model="slotForm.description" type="textarea"/></el-form-item><el-form-item label="排序"><el-input-number v-model="slotForm.sortOrder"/></el-form-item><el-form-item label="启用"><el-switch v-model="slotForm.enabled"/></el-form-item></el-form><template #footer><el-button @click="slotDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveSlot">保存</el-button></template></el-dialog><el-dialog v-model="adDialog" :title="editingAd?'编辑广告':'新增广告'" width="620px"><el-form label-width="100px"><el-form-item label="标题"><el-input v-model="adForm.title"/></el-form-item><el-form-item label="图片路径"><el-input v-model="adForm.imagePath" placeholder="/static/..."/></el-form-item><el-form-item label="目标地址"><el-input v-model="adForm.url"/></el-form-item><el-form-item label="打开方式"><el-select v-model="adForm.openMode" style="width:100%"><el-option label="按目标默认" value="DEFAULT"/><el-option label="当前窗口" value="SAME_WINDOW"/><el-option label="新窗口" value="NEW_WINDOW"/></el-select></el-form-item><el-form-item label="开始时间"><el-date-picker v-model="adForm.startAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" clearable/></el-form-item><el-form-item label="结束时间"><el-date-picker v-model="adForm.endAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss" clearable/></el-form-item><el-form-item label="排序"><el-input-number v-model="adForm.sortOrder"/></el-form-item><el-form-item label="启用"><el-switch v-model="adForm.enabled"/></el-form-item></el-form><template #footer><el-button @click="adDialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveAd">保存</el-button></template></el-dialog></main></template>
